/* ============================================================
   Anciens Suzerains — mise en page
   Chaque Suzerain dans son propre encadré, empilés verticalement.
   ============================================================ */
.cp-suzerain {
  border: 1px solid color-mix(in srgb, #7a1010 16%, var(--lightgray));
  border-radius: 8px;
  padding: 0.9rem 1.1rem 1.1rem;
  margin: 1.4rem 0;
  background: color-mix(in srgb, var(--light) 92%, var(--gray));
}
.cp-suzerain &gt; h3 {
  margin: 0 0 0.6rem;
  padding-bottom: 0.4rem;
  border-bottom: 2px solid var(--secondary);
  font-variant: small-caps;
  letter-spacing: 0.03em;
  color: var(--secondary);
}
.cp-suzerain-lien {
  margin: 0 0 1rem;
  padding: 0.5rem 0.8rem;
  border-left: 3px solid var(--tertiary);
  background: var(--light);
  border-radius: 0 4px 4px 0;
  font-size: 0.92rem;
  line-height: 1.5;
}

/* ============================================================
   Tableaux de statistiques — alignement resserré
   ============================================================ */
table thead tr {
  border-bottom: 2px solid color-mix(in srgb, #7a1010 35%, var(--lightgray));
}
table td, table th {
  font-variant-numeric: tabular-nums;
  text-align: center;
  padding: 0.35rem 0.5rem;
}
table td:first-child, table th:first-child {
  text-align: left;
}

/* ============================================================
   Titres encadrés — flanqués du même losange que le séparateur
   ============================================================ */
.cp-domaine &gt; h2::before,
.cp-domaine &gt; h2::after,
.cp-niveau &gt; h3::before,
.cp-niveau &gt; h3::after {
  content: &quot;◆&quot;;
  color: color-mix(in srgb, #000000 45%, var(--lightgray));
  font-size: 0.6rem;
  margin: 0 0.5rem;
  vertical-align: middle;
  border-bottom: none;
}

.cp-suzerain-lien p { margin: 0 0 0.3rem; }
.cp-suzerain-lien ul { margin: 0.2rem 0 0; padding-left: 1.1rem; }
.cp-suzerain-lien li { margin: 0.25rem 0; }

/* ============================================================
   Titres des Anciens Suzerains — variante rouge sang de .legendary
   Même rouge (#7a1010) que les bordures et le séparateur, pour
   que tout vienne d&#039;une seule et même teinte sur cette page.
   ============================================================ */
.legendary-crimson h3 {
  background: linear-gradient(
    135deg,
    #7a1010,
    #a3161d 30%,
    #e0393e 50%,
    #a3161d 70%,
    #7a1010
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  -webkit-text-fill-color: transparent;
  animation: legendary-shimmer 4s ease-in-out infinite;
}

[saved-theme=&quot;dark&quot;] .legendary-crimson {
  background:
    linear-gradient(var(--light), var(--light)) padding-box,
    linear-gradient(
      135deg,
      #7a1010 0%,
      #b1181f 25%,
      #ffb3b3 50%,
      #b1181f 75%,
      #7a1010 100%
    ) border-box;
}
[saved-theme=&quot;dark&quot;] .legendary-crimson h3 {
  background: linear-gradient(
    135deg,
    #7a1010,
    #b1181f 30%,
    #ffb3b3 50%,
    #b1181f 70%,
    #7a1010
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
}

/* ============================================================
   Domaines de magie ============================================================ */
.cp-domaine {
