.cp-encadre ul { margin: 0; padding-left: 1.1rem; }
.cp-encadre li { margin: 0.4rem 0; line-height: 1.5; }

/* ============================================================
   Séparateur signature — remplace les --- entre grandes sections
   ============================================================ */
.cp-diviseur {9
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin: 1.8rem 0;
  color: color-mix(in srgb, #000000 45%, var(--lightgray));
}
.cp-diviseur::before,
.cp-diviseur::after {
  content: &quot;&quot;;
