/* ============================================================
   Mobile
   ============================================================ */
@media (max-width: 700px) {
  .cp-sorts { grid-auto-flow: row; }
  .cp-sort + .cp-sort {
    border-left: none;
    border-top: 1px solid var(--lightgray);
    padding-left: 0.2rem;
    padding-top: 0.7rem;
  }
}

